#!/usr/bin/env sh
# Generates the Homebrew cask for Ponder (to stdout) from a release version + the .dmg's checksum.
# The release workflow uses this to push a bump to fredoliveira/homebrew-tap on every tagged
# release; it also works by hand:
#
#   generate.sh <version> <sha256-dmg>
#
# <version> is bare (0.2.1), not the tag (v0.2.1).
set -eu

if [ $# -ne 2 ]; then
  echo "usage: generate.sh <version> <sha256-dmg>" >&2
  exit 64
fi
version="$1"
sha_dmg="$2"

cat <<CASK
# Homebrew Cask for Ponder, the MTG Arena draft side panel.
#
# GENERATED by packaging/homebrew/generate.sh in fredoliveira/ponder - the release
# workflow pushes a bump here on every tagged release. Edit the generator, not this file.
#
# Users install with:
#
#     brew install --cask fredoliveira/tap/ponder
#
# The app is signed with a Developer ID and notarized by Apple (release.yml).
cask "ponder" do
  version "${version}"
  sha256 "${sha_dmg}"

  url "https://github.com/fredoliveira/ponder/releases/download/v#{version}/Ponder.dmg"
  name "Ponder"
  desc "MTG Arena draft side panel showing 17Lands win rates"
  homepage "https://github.com/fredoliveira/ponder"

  depends_on macos: :sonoma

  app "Ponder.app"

  uninstall quit: "com.helloform.ponder"

  zap trash: [
    "~/Library/Caches/ponder",
    "~/Library/Preferences/com.helloform.ponder.plist",
  ]
end
CASK
